// =============================================================================
// tb_pe_array.v -- unit testbench for pe_array / mac_lane.
//
// Uses the vectors from golden/unit/ (generated by sim/reference_model.py):
//
//   pe_w.mem / pe_a.mem   NJOBS*9 words of 32 lanes, job-major tap-minor
//   pe_b.mem / pe_s.mem   NJOBS*32 biases / shifts, job-major lane-minor
//   pe_y.mem              NJOBS*32 expected outputs, same order as pe_b
//
// 31 jobs x 9 taps.  They cover plain accumulation, every shift boundary
// (0, 1, 8, 15), saturation at 255, a strongly negative bias that must be killed
// by the ReLU clamp, and a full-scale stress job (|w|=127, a=255).
//
// The schedule mirrors what the real engines will do, with no idle cycles:
//
//   * consecutive jobs alternate accumulators (SEL = 0/1), so the array's second
//     bank is exercised and a bank mix-up would fail the test;
//   * consecutive jobs alternate accumulators (SEL = 0/1), so both banks are
//     exercised and a bank mix-up would fail the test;
//   * each job is loaded, run, then drained.  The tighter schedule -- draining
//     job j in the first tap cycle of job j+1 -- is exercised by the engine
//     testbench instead, because it needs consecutive jobs to share constants
//     (which is what the real loop order guarantees).
//
// Run from the project root:  bash sim/run.sh pe
// =============================================================================
`timescale 1ns / 1ps

module tb_pe_array;

    localparam integer LANES      = 32;
    localparam integer T          = 9;      // taps per job
    localparam integer NJOBS      = 31;
    localparam integer W_BITS     = 8;
    localparam integer ACT_BITS   = 8;
    localparam integer ACC_BITS   = 24;
    localparam integer SHIFT_BITS = 4;
    localparam real    CLK_NS     = 20.833; // 48 MHz

    // ---- DUT signals -------------------------------------------------------
    reg                            clk = 1'b0;
    reg                            rst_n = 1'b0;
    reg                            load_const = 1'b0;
    reg  [4:0]                     load_lane = 5'd0;
    reg  [ACC_BITS-1:0]            load_bias = {ACC_BITS{1'b0}};
    reg  [SHIFT_BITS-1:0]          load_shift = {SHIFT_BITS{1'b0}};
    reg                            en = 1'b0;
    reg                            init = 1'b0;
    reg                            sel = 1'b0;
    reg                            rd_sel = 1'b0;
    reg  [LANES*W_BITS-1:0]        w_word = {LANES*W_BITS{1'b0}};
    reg  [LANES*ACT_BITS-1:0]      a_word = {LANES*ACT_BITS{1'b0}};
    wire [LANES*ACT_BITS-1:0]      y_word;
    wire [LANES*ACC_BITS-1:0]      acc_a_word, acc_b_word;
    wire                           ovf;

    // ---- golden vectors ----------------------------------------------------
    reg [LANES*W_BITS-1:0]   w_mem [0:NJOBS*T-1];
    reg [LANES*ACT_BITS-1:0] a_mem [0:NJOBS*T-1];
    reg [ACC_BITS-1:0]       b_mem [0:NJOBS*LANES-1];
    reg [SHIFT_BITS-1:0]     s_mem [0:NJOBS*LANES-1];
    reg [ACT_BITS-1:0]       y_mem [0:NJOBS*LANES-1];

    integer errors = 0;
    integer checks = 0;

    always #(CLK_NS/2.0) clk = ~clk;

    // ---- device under test -------------------------------------------------
    pe_array #(
        .LANES (LANES), .W_BITS (W_BITS), .ACT_BITS (ACT_BITS),
        .ACC_BITS (ACC_BITS), .SHIFT_BITS (SHIFT_BITS)
    ) u_dut (
        .clk        (clk),
        .rst_n      (rst_n),
        .load_const (load_const),
        .load_lane  (load_lane),
        .load_bias  (load_bias),
        .load_shift (load_shift),
        .en         (en),
        .init       (init),
        .sel        (sel),
        .rd_sel     (rd_sel),
        .w_word     (w_word),
        .a_word     (a_word),
        .y_word     (y_word),
        .acc_a_word (acc_a_word),
        .acc_b_word (acc_b_word),
        .ovf        (ovf)
    );

    // ---- helpers -----------------------------------------------------------
    task load_constants;
        input integer jj;
        integer k;
        begin
            for (k = 0; k < LANES; k = k + 1) begin
                @(negedge clk);
                load_const = 1'b1;
                load_lane  = k;
                load_bias  = b_mem[jj*LANES + k];
                load_shift = s_mem[jj*LANES + k];
            end
            @(negedge clk);
            load_const = 1'b0;
        end
    endtask

    // Check one job's 32 output lanes.  Called right after the posedge that
    // starts the *next* job, so y_word still shows the finished accumulator.
    task check_job;
        input integer jj;
        integer lane;
        begin
            for (lane = 0; lane < LANES; lane = lane + 1) begin
                checks = checks + 1;
                if (y_word[lane*ACT_BITS +: ACT_BITS] !== y_mem[jj*LANES + lane]) begin
                    errors = errors + 1;
                    if (errors < 12)
                        $display("  FAIL job %0d lane %0d: got %02x expected %02x",
                                 jj, lane, y_word[lane*ACT_BITS +: ACT_BITS],
                                 y_mem[jj*LANES + lane]);
                end
            end
        end
    endtask

    // ---- main --------------------------------------------------------------
    integer jj, tt;

    initial begin
        if ($test$plusargs("vcd")) begin
            $dumpfile("sim/build/tb_pe_array.vcd");
            $dumpvars(0, tb_pe_array);
        end
        $readmemh("golden/unit/pe_w.mem", w_mem);
        $readmemh("golden/unit/pe_a.mem", a_mem);
        $readmemh("golden/unit/pe_b.mem", b_mem);
        $readmemh("golden/unit/pe_s.mem", s_mem);
        $readmemh("golden/unit/pe_y.mem", y_mem);

        repeat (3) @(negedge clk);
        rst_n = 1'b1;
        @(negedge clk);

        en = 1'b0;
        for (jj = 0; jj < NJOBS; jj = jj + 1) begin
            load_constants(jj);

            for (tt = 0; tt < T; tt = tt + 1) begin
                en     = 1'b1;
                init   = (tt == 0);
                sel    = jj % 2;
                rd_sel = jj % 2;
                w_word = w_mem[jj*T + tt];
                a_word = a_mem[jj*T + tt];
                @(negedge clk);
            end

            // one drain cycle: bank read-out is combinational
            en = 1'b0;
            rd_sel = jj % 2;
            @(posedge clk);
            check_job(jj);
            @(negedge clk);
        end

        if (ovf) begin
            errors = errors + 1;
            $display("  FAIL: accumulator overflow flag raised");
        end
        if (errors == 0)
            $display("PE ARRAY: %0d/%0d lane results match the golden model", checks, checks);
        else
            $display("PE ARRAY: %0d of %0d lane results WRONG", errors, checks);
        $finish;
    end

endmodule
